import{_ as n,o as h,c as i,a5 as c}from"./chunks/framework.CsGesDJn.js";const s=JSON.parse('{"title":"Kịch bản test Credit trên Web","description":"","frontmatter":{},"headers":[],"relativePath":"feature/subscription-billing/member-credit/manual-test.md","filePath":"feature/subscription-billing/member-credit/manual-test.md"}'),e={name:"feature/subscription-billing/member-credit/manual-test.md"};function r(a,t,d,g,o,l){return h(),i("div",null,[...t[0]||(t[0]=[c('<h1 id="kich-ban-test-credit-tren-web" tabindex="-1">Kịch bản test Credit trên Web <a class="header-anchor" href="#kich-ban-test-credit-tren-web" aria-label="Permalink to &quot;Kịch bản test Credit trên Web&quot;">​</a></h1><h2 id="pham-vi-kiem-thu-ai-credit" tabindex="-1">Phạm vi kiểm thử AI Credit <a class="header-anchor" href="#pham-vi-kiem-thu-ai-credit" aria-label="Permalink to &quot;Phạm vi kiểm thử AI Credit&quot;">​</a></h2><p>Mục này thay thế ghi chú cũ bên dưới về “chưa nối AI”. Mỗi môi trường cần có schema Credit phù hợp và Agency kiểm thử được cấp quỹ hợp lệ theo quyền của môi trường đó. Không giả định dữ liệu, tài khoản hay khoản cấp thử trên máy của người khác tồn tại. Script cấp quỹ/sửa dữ liệu dành riêng cho một máy không nằm trong repository; không tạo subscription hoặc thanh toán giả. Xem hướng dẫn triển khai chung tại <a href="./../../credit-unification/rollout.html">Credit unification</a>.</p><h3 id="truoc-khi-test-ai" tabindex="-1">Trước khi test AI <a class="header-anchor" href="#truoc-khi-test-ai" aria-label="Permalink to &quot;Trước khi test AI&quot;">​</a></h3><ol><li>Restart Business bằng code mới và AI Service để áp dụng internal-key guard của hashtag; Gateway/Web chạy bình thường. Chỉ migrate nhưng giữ binary cũ thì chưa hạch toán AI đúng. Không đổi khóa nội bộ.</li><li>Chọn Workspace thuộc Agency kiểm thử đã được cấp quỹ trên chính môi trường đang dùng.</li><li>Admin kiểm tra <code>/admin/credit-prices</code>. Lúc seed, giá mới nhất: CONTENT_GENERATE=3, AMBASSADOR_GENERATE=10. Thao tác khác chưa có giá phải cấu hình trước; không tự miễn phí. Không tự đổi giá để khớp ví dụ.</li><li>Manager/Creator cần membership Agency/Workspace hoạt động. Mặc định 10/kỳ nếu Owner chưa cấu hình; Owner không có trần cá nhân nhưng vẫn chịu quỹ chung. Đã chốt mở Editor và AI Studio cho Owner dùng AI; quyền sửa Task/gửi duyệt/xuất bản ở Backend không thay đổi.</li></ol><h3 id="kich-ban-ai" tabindex="-1">Kịch bản AI <a class="header-anchor" href="#kich-ban-ai" aria-label="Permalink to &quot;Kịch bản AI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Thao tác</th><th>Kỳ vọng</th></tr></thead><tbody><tr><td>Mở báo cáo Agency kiểm thử trước lần tạo đầu</td><td>Số dư và nguồn quỹ khớp khoản cấp hợp lệ trên môi trường đó; không giả định sẵn 100 credit.</td></tr><tr><td>Tạo nội dung thành công, giá vẫn 3</td><td>Còn 97; usage người gửi tăng 3, held=0. Áp dụng lại kết quả vào Editor không trừ thêm.</td></tr><tr><td>Bấm tạo lại có chủ ý</td><td>Mã yêu cầu mới; thành công trừ thêm theo giá lúc gửi.</td></tr><tr><td>Retry kỹ thuật cùng payload và Idempotency-Key</td><td>Không gọi/trừ lần hai; đang chạy báo pending, đã xong trả kết quả đã lưu. Không đổi payload với cùng mã.</td></tr><tr><td>Thành viên trần 10, đã dùng 9, tạo thêm giá 3</td><td>Chặn CREDIT_MEMBER_LIMIT_REACHED trước khi gọi AI.</td></tr><tr><td>Thao tác chưa có giá</td><td>CREDIT_PRICE_NOT_CONFIGURED; không gọi AI/giữ credit.</td></tr><tr><td>Ambassador thành công giá 10</td><td>Trừ 10. Character Sheet/commercial cần giá riêng; không tính số panel thành nhiều ảnh.</td></tr><tr><td>Video đang xử lý</td><td>Giữ giá một video, chưa tăng used. Đóng Editor vẫn có worker đối soát.</td></tr><tr><td>Video COMPLETED có URL</td><td>Trừ đúng một lần theo giá lúc gửi; Admin đổi giá/poll lại không đổi khoản này.</td></tr><tr><td>Video FAILED/kết quả đồng bộ xác nhận không có đầu ra</td><td>Giải phóng hold, không tăng used.</td></tr><tr><td>Timeout/mất kết nối/HTTP 5xx chưa rõ kết quả</td><td>Báo cần đối soát, giữ credit; không tự hoàn/gọi lại provider. Không bấm tạo mới để retry kỹ thuật. Chưa có UI Admin xử lý thủ công kết quả mơ hồ.</td></tr></tbody></table><p>Không dùng seed để reset số đã dùng/đang giữ; không xóa reservation hoặc tạo thanh toán giả. Các test cấu hình phía dưới vẫn áp dụng, nhưng quỹ không còn 0 sau seed.</p><h2 id="_1-kiem-tra-schema-truoc-khi-test" tabindex="-1">1. Kiểm tra schema trước khi test <a class="header-anchor" href="#_1-kiem-tra-schema-truoc-khi-test" aria-label="Permalink to &quot;1. Kiểm tra schema trước khi test&quot;">​</a></h2><p>Kiểm tra schema PostgreSQL thực tế và chỉ áp dụng migration còn thiếu theo thứ tự phụ thuộc:</p><ol><li><code>2026-10-19-member-credit-configuration.sql</code>.</li><li><code>2026-10-20-credit-accounting.sql</code>.</li></ol><p>Đối chiếu các migration AI execution, nguồn quỹ và unified credit trong README migration/rollout hiện tại trước khi test AI. Không chạy init trên DB có dữ liệu, không replay toàn bộ thư mục migration và không dùng script sửa dữ liệu của máy khác.</p><p>Không suy ra số dòng, cấu hình hạn mức hoặc số dư từ kết quả trên môi trường khác. Dữ liệu ledger/Creator limit cũ không tự nhập vào báo cáo mới.</p><p><strong>Lưu ý:</strong> các thao tác test bên dưới sẽ lưu cấu hình thật. Dùng Agency dành cho kiểm thử, ghi lại cấu hình/giá trước khi đổi; không dùng Agency của thành viên khác. Chưa có thao tác xóa override để quay lại kế thừa trên UI/API; dùng một thành viên khác chưa có override để kiểm tra kế thừa. Giá là lịch sử append-only: khôi phục bằng cách lưu phiên bản mới, không DELETE lịch sử.</p><h2 id="_2-chuan-bi" tabindex="-1">2. Chuẩn bị <a class="header-anchor" href="#_2-chuan-bi" aria-label="Permalink to &quot;2. Chuẩn bị&quot;">​</a></h2><ul><li>Restart Business bằng code Credit compact mới nhất, chạy Gateway và Web hiện tại. Migration không tự khởi động lại service.</li><li>Chuẩn bị Owner đúng Agency, hai thành viên nội bộ để thử kế thừa/override, Manager/Creator và một Admin. Client dùng để kiểm tra chặn truy cập. Manager/Creator phải thực sự thuộc Agency; role Workspace không thay thế membership Agency.</li><li>Vào Agency, chọn <strong>AI Credit</strong>, hoặc mở <code>http://localhost:3000/agency/{agencyId}/credit</code>.</li><li>Admin mở <code>http://localhost:3000/admin/credit-prices</code>.</li><li>Chọn Agency kiểm thử mà tài khoản có đúng quyền Owner/thành viên trên môi trường đang dùng; không sao chép ID Agency từ máy khác.</li><li>Mở DevTools → Network khi cần xem request/status. Không gửi token hay thông tin đăng nhập cho người khác.</li></ul><h2 id="_3-nhung-phan-test-đuoc-ngay" tabindex="-1">3. Những phần test được ngay <a class="header-anchor" href="#_3-nhung-phan-test-đuoc-ngay" aria-label="Permalink to &quot;3. Những phần test được ngay&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Vai trò / thao tác</th><th>Kết quả mong đợi</th></tr></thead><tbody><tr><td>C01</td><td>Owner mở AI Credit sau migration, trước khi cấu hình</td><td>Quỹ Plan/mua thêm/đang giữ đều 0. Hạn mức mặc định để trống vì chưa cấu hình, không tự ghi 0 hoặc cấp tiền.</td></tr><tr><td>C02</td><td>Owner chọn một thành viên chưa có override</td><td>Một lần bấm mở chi tiết; hạn mức hiệu lực là 10 từ hệ thống. Không tải chi tiết Credit cho mọi thành viên ngay khi mở trang.</td></tr><tr><td>C03</td><td>Owner lưu hạn mức mặc định 20</td><td>Lưu thành công; revision tăng. Thành viên chưa có override nhận mức 20; quỹ vẫn 0. Reload trang vẫn giữ cấu hình.</td></tr><tr><td>C04</td><td>Owner đặt riêng thành viên A là 30</td><td>A có nguồn “Hạn mức riêng”, giữ 30 sau reload. Thành viên B chưa có override vẫn kế thừa 20. Mức 30 lớn hơn quỹ 0 vẫn được cấu hình vì đây là trần, không phải chia tiền.</td></tr><tr><td>C05</td><td>Owner đổi mặc định 20 → 25</td><td>A vẫn 30; B nhận 25 khi đọc lại. Nếu đang nhập draft chưa lưu ở form thành viên, refresh mặc định không được xóa draft. Bấm tải lại form để nhận giá trị đã lưu.</td></tr><tr><td>C06</td><td>Owner đặt hạn mức riêng A là 0</td><td>Hiển thị 0, không biến thành không giới hạn. Đăng nhập A thấy mức 0. Chưa dùng Generate để chứng minh bị chặn vì AI chưa nối Credit.</td></tr><tr><td>C07</td><td>Owner đặt mặc định 0</td><td>Thành viên chưa có override nhận 0; A có override vẫn theo mức riêng. Không xóa hoặc hoàn tiền bất kỳ khoản nào.</td></tr><tr><td>C08</td><td>Nhập rỗng, -1, 1.5, 1e3 hoặc 9007199254740992 vào form hạn mức/giá</td><td>Lỗi tại ô nhập; không gửi PUT. Nhập số nguyên hợp lệ rồi Enter hoặc Lưu đều hoạt động. Không có hộp thoại mặc định của trình duyệt.</td></tr><tr><td>C09</td><td>Hai tab Owner cùng đọc một phiên bản chính sách; tab A lưu 20, tab B lưu 30 mà chưa tải lại</td><td>Tab B nhận 409, giữ draft 30 và khóa lưu phiên bản cũ. Tải lại nhận 20, sau đó mới sửa/lưu tiếp.</td></tr><tr><td>C10</td><td>Nhập draft 77 nhưng không lưu, bấm “Tải lại bản đã lưu”</td><td>Trở lại giá trị thực do server trả về, kể cả revision không đổi. Không tự gửi draft.</td></tr><tr><td>C11</td><td>Owner mở “Xem sử dụng của tôi”</td><td>Có thông tin Owner không có trần cá nhân. Với DB chưa được cấp credit/cycle, phần usage hiển thị trạng thái chưa thiết lập kỳ, không dựng số liệu 0 giả.</td></tr><tr><td>C12</td><td>Manager/Creator mở AI Credit</td><td>Chỉ thấy hạn mức hiệu lực, nguồn hạn mức, usage của mình và bảng giá chỉ đọc. Không có form đặt hạn mức hoặc quỹ chung của Owner. Network không gọi các API Owner-only.</td></tr><tr><td>C13</td><td>Client mở URL AI Credit; thử cả URL có dấu / cuối</td><td>Không vào được màn hình Credit. Non-admin mở <code>/admin/credit-prices</code> cũng bị chặn.</td></tr><tr><td>C14</td><td>Chuyển Agency hoặc đăng xuất rồi đăng nhập thành viên khác</td><td>Không giữ quỹ/form/quyền Owner của Agency hoặc người trước. Owner Agency A không có quyền chỉnh chính sách Agency B nếu chỉ là thành viên B.</td></tr><tr><td>C15</td><td>Tìm thành viên theo tên/email rồi chọn A/B</td><td>Danh sách lọc đúng; chi tiết đúng người. Không có Owner trong danh sách chỉnh hạn mức riêng. Không lẫn input/usage giữa A và B.</td></tr></tbody></table><h2 id="_4-admin-cau-hinh-gia" tabindex="-1">4. Admin cấu hình giá <a class="header-anchor" href="#_4-admin-cau-hinh-gia" aria-label="Permalink to &quot;4. Admin cấu hình giá&quot;">​</a></h2><p>Các con số sau <strong>chỉ là giá test tự chọn</strong>, không phải bảng giá nghiệp vụ đã chốt. Ghi lại trạng thái cũ trước khi thay đổi.</p><table tabindex="0"><thead><tr><th>ID</th><th>Thao tác</th><th>Kết quả mong đợi</th></tr></thead><tbody><tr><td>P01</td><td>Admin mở trang giá sau migration chưa có giá</td><td>Ô giá trống và có trạng thái chưa cấu hình; không hiểu là miễn phí.</td></tr><tr><td>P02</td><td>Chọn CONTENT_GENERATE, nhập giá test 3, bật sử dụng rồi lưu</td><td>Có phiên bản giá mới. Nếu chưa có lịch sử, revision là 1. Member mở bảng giá thấy 3 credit/yêu cầu.</td></tr><tr><td>P03</td><td>Đổi cùng thao tác thành 5 và lưu</td><td>Revision tăng; API GET giá trả bản mới nhất. Không có nút sửa/xóa phiên bản lịch sử.</td></tr><tr><td>P04</td><td>Đặt giá test 0 và bật sử dụng</td><td>Hiển thị 0 rõ ràng, khác với chưa cấu hình. Đây chỉ là cấu hình miễn phí có chủ đích, chưa chứng minh flow AI đã dùng giá này.</td></tr><tr><td>P05</td><td>Ngừng sử dụng giá rồi mở bảng giá bằng Member</td><td>Giá vẫn hiển thị nhưng trạng thái tạm ngừng; không trở thành chưa cấu hình hoặc 0.</td></tr><tr><td>P06</td><td>Lần lượt chọn nội dung/caption/hashtag, ảnh/đại sứ/bộ nhân vật và video</td><td>Hiện đơn vị theo yêu cầu, ảnh hoặc video thành công. Bộ nhân vật tính ảnh đầu ra, không tính số ô trong ảnh.</td></tr><tr><td>P07</td><td>Hai tab Admin sửa cùng operation từ cùng revision</td><td>Một bản lưu thành công, bản cũ nhận 409 và yêu cầu tải lại; không ghi đè im lặng.</td></tr></tbody></table><h2 id="_5-phan-biet-chua-thiet-lap-ky-voi-loi" tabindex="-1">5. Phân biệt chưa thiết lập kỳ với lỗi <a class="header-anchor" href="#_5-phan-biet-chua-thiet-lap-ky-voi-loi" aria-label="Permalink to &quot;5. Phân biệt chưa thiết lập kỳ với lỗi&quot;">​</a></h2><p><strong>Kết quả đúng với DB vừa migrate:</strong></p><ul><li><code>GET /api/v1/agencies/{agencyId}/credit/balance</code> bằng Owner trả 200 với quỹ 0.</li><li>Các GET/PUT policy và hạn mức hoạt động sau khi Business đã nạp API mới.</li><li><code>GET .../credit/usage/me</code> hoặc <code>GET .../credit/members/{memberId}/usage</code> trả <strong>409 CREDIT_ACCOUNT_NOT_READY</strong>, vì chưa có grant hợp lệ thiết lập <code>credit_cycle_anchor</code>.</li><li>Web vẫn xem/sửa được cấu hình; báo cáo theo kỳ hiện thông báo chuẩn bị tích hợp, không coi đó là thiếu migration.</li><li>Nếu vẫn nhận <strong>503 CREDIT_SCHEMA_NOT_READY</strong>, kiểm tra Business có kết nối đúng PostgreSQL local <code>brandhub</code>, đúng code/schema compact hay không. Không chạy init hoặc xóa bảng để thử.</li><li>Nếu nhận 404 endpoint mới, kiểm tra/restart đúng Business build và Gateway. Nếu 401, đăng nhập lại và kiểm tra luồng xác thực, không seed DB để xử lý lỗi quyền.</li></ul><h2 id="_6-phan-chua-test-đuoc-xuyen-suot-tu-web" tabindex="-1">6. Phần chưa test được xuyên suốt từ Web <a class="header-anchor" href="#_6-phan-chua-test-đuoc-xuyen-suot-tu-web" aria-label="Permalink to &quot;6. Phần chưa test được xuyên suốt từ Web&quot;">​</a></h2><p>Hiện chưa nối các API AI và thanh toán/subscription vào accounting. Vì vậy:</p><ul><li>Bấm Generate chưa phải bằng chứng credit đã được giữ/trừ/hoàn.</li><li>Mua/gia hạn subscription không được giả định đã cấp quỹ mới.</li><li>Chưa có nút cấp tiền, grant/reserve/settle public hoặc bộ lọc lịch sử nhiều kỳ trên Web.</li><li>Không tự INSERT grant/transaction giả hoặc chỉnh cycle anchor trên DB đang dùng để làm báo cáo có số liệu.</li></ul><p>Khi có môi trường test riêng và nguồn grant hợp lệ, kiểm tra tiếp:</p><table tabindex="0"><thead><tr><th>ID</th><th>Điều kiện / thao tác</th><th>Mong đợi</th></tr></thead><tbody><tr><td>F01</td><td>Quỹ ban đầu Plan 100 + mua thêm 50, thành viên có trần 10; giữ 2 ảnh giá test 3/ảnh</td><td>Plan khả dụng 94, mua thêm 50, tổng khả dụng 144, đang giữ 6. Hạn mức cá nhân còn 4.</td></tr><tr><td>F02</td><td>Tác vụ F01 chỉ thành công 1 ảnh, xác nhận quyết toán</td><td>Đã dùng 3, đang giữ 0, Plan khả dụng 97, tổng khả dụng 147; hạn mức còn 7. Hoàn phần giữ dư về đúng nguồn.</td></tr><tr><td>F03</td><td>Gửi lại cùng request kỹ thuật / nhận callback lặp</td><td>Không giữ/trừ lặp. Chủ động tạo lại nội dung là yêu cầu mới.</td></tr><tr><td>F04</td><td>Hai yêu cầu đồng thời vượt trần cá nhân/quỹ chung</td><td>Không vượt giới hạn; chỉ yêu cầu đủ điều kiện được giữ tiền.</td></tr><tr><td>F05</td><td>Sang kỳ subscription tiếp theo</td><td>Usage kỳ mới tính lại; hạn mức Owner đã đặt giữ nguyên. Credit Plan cũ không rollover, mua thêm còn dư vẫn được dùng.</td></tr><tr><td>F06</td><td>Tác vụ kỳ cũ hoàn tất sau khi sang kỳ mới</td><td>Tính theo giá và kỳ của yêu cầu gốc; không cộng vào usage kỳ mới.</td></tr></tbody></table><p>Các ca lõi này đã được kiểm tra bằng service/JDBC trên PostgreSQL cô lập; <strong>chưa xác nhận flow browser → provider/payment thật</strong>.</p><h2 id="_7-kiem-tra-ui-va-ghi-nhan-loi" tabindex="-1">7. Kiểm tra UI và ghi nhận lỗi <a class="header-anchor" href="#_7-kiem-tra-ui-va-ghi-nhan-loi" aria-label="Permalink to &quot;7. Kiểm tra UI và ghi nhận lỗi&quot;">​</a></h2><ul><li>Chuyển Việt/Anh, sáng/tối; thử 375/768/1440px. Nhãn/số liệu không tràn trang; bảng được phép cuộn nội bộ khi dữ liệu dài.</li><li>Thử bàn phím, Enter lưu, nút <code>?</code>, tìm/chọn thành viên. Thông báo lỗi không làm mất nội dung chưa lưu.</li><li>Dùng DevTools Request blocking chặn riêng GET <code>/credit/usage/me</code>, rồi bấm làm mới: hiện lỗi và thử lại, không thay bằng usage 0. Bỏ chặn rồi thử lại; không cần tắt toàn bộ mạng hoặc reload khi đang offline.</li><li>Khi báo lỗi, gửi vai trò, Agency ID, URL, thao tác, status/error code và requestId. Không gửi Authorization/Cookie/token.</li><li>Không gọi các endpoint Billing placeholder: <code>/api/v1/billing/credits/buy</code>, <code>/api/v1/billing/credits/{agencyId}/usage</code>, <code>/api/v1/billing/credits/{agencyId}/limits</code>.</li></ul>',32)])])}const m=n(e,[["render",r]]);export{s as __pageData,m as default};
